insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('redisenar-un-material-educativo-para-convertir-un-tema-complejo','educacion',array['arte']::text[],'Rediseñar un material educativo para convertir un tema complejo en una explicación sencilla','Toma un material difícil de seguir, como unas diapositivas o un capítulo, y rediséñalo para principiantes con mejor orden, ejemplos y visuales, comparando cómo se entienden antes y después.','Prototipo','3 a 4 semanas',24,array['Material educativo','Rediseño']::text[],array['crear']::text[],'ficticios',NULL,'educacion psicologia ingenieria de sistemas comunicaciones diseno trabajo social sociologia administracion diseno instruccional. redaccion clara. diseno visual. pruebas con usuarios. un editor de documentos o presentaciones. un editor de graficos. tres lectores voluntarios.',$a40sld${"id": "redisenar-un-material-educativo-para-convertir-un-tema-complejo", "area": "educacion", "areas2": ["arte"], "titulo": "Rediseñar un material educativo para convertir un tema complejo en una explicación sencilla", "resumen": "Toma un material difícil de seguir, como unas diapositivas o un capítulo, y rediséñalo para principiantes con mejor orden, ejemplos y visuales, comparando cómo se entienden antes y después.", "tipo": "Prototipo", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Material educativo", "Rediseño"], "intencion": ["crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Educación", "Psicología", "Ingeniería de Sistemas", "Comunicaciones", "Diseño", "Trabajo Social", "Sociología", "Administración"], "problema": ["Muchos materiales educativos están pensados para quien ya sabe el tema: parten de definiciones, usan términos sin explicarlos y tienen demasiado texto. Quien empieza se pierde.", "Rediseñarlos pensando en el lector novato mejora mucho la comprensión."], "desarrollar": ["Elige un material sobre un tema que domines, identifica qué lo hace difícil, como orden, vocabulario o falta de ejemplos, y rediséñalo con una estructura más clara, ejemplos concretos y recursos visuales sencillos.", "Pídele a tres personas que no conozcan el tema que estudien la versión original o la rediseñada y respondan preguntas de comprensión. Compara resultados y comentarios y ajusta."], "ampliaciones": [{"titulo": "Versión resumida", "aporta": "crea una versión de una página para repaso rápido."}, {"titulo": "Versión visual", "aporta": "convierte el material en infografía o esquema."}, {"titulo": "Lista de verificación", "aporta": "crea una lista para evaluar si un material es claro."}], "objetivos": ["Diagnosticar problemas de un material.", "Rediseñarlo para principiantes.", "Comparar comprensión antes y después.", "Documentar el proceso."], "habilidades": ["Diseño instruccional.", "Redacción clara.", "Diseño visual.", "Pruebas con usuarios."], "herramientas": ["Un editor de documentos o presentaciones.", "Un editor de gráficos.", "Tres lectores voluntarios."], "lineamientos": ["Usa material propio o con licencia abierta y cita siempre la fuente del original.", "No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión."], "otroSector": "El mismo rediseño sirve para manuales de usuario, instructivos o informes técnicos."}$a40sld$::jsonb,47),
('como-se-puede-ensenar-un-concepto-abstracto-mediante-ejemplos-de','educacion',array['ciencias']::text[],'¿Cómo se puede enseñar un concepto abstracto mediante ejemplos de la vida cotidiana?','Elige un concepto abstracto, como una función, una probabilidad o un algoritmo, y diseña ejemplos de la vida diaria que lo expliquen, probando cuáles se entienden mejor y dónde falla la comparación.','Prototipo','3 semanas',22,array['Ejemplos cotidianos','Conceptos abstractos']::text[],array['crear','investigar']::text[],'ficticios',NULL,'educacion biologia fisica quimica matematica diseno psicologia comunicaciones pensamiento analogico. comunicacion. diseno didactico. analisis critico. un editor de documentos. hojas para dibujar. tres personas voluntarias.',$a41sld${"id": "como-se-puede-ensenar-un-concepto-abstracto-mediante-ejemplos-de", "area": "educacion", "areas2": ["ciencias"], "titulo": "¿Cómo se puede enseñar un concepto abstracto mediante ejemplos de la vida cotidiana?", "resumen": "Elige un concepto abstracto, como una función, una probabilidad o un algoritmo, y diseña ejemplos de la vida diaria que lo expliquen, probando cuáles se entienden mejor y dónde falla la comparación.", "tipo": "Prototipo", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Ejemplos cotidianos", "Conceptos abstractos"], "intencion": ["crear", "investigar"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Educación", "Biología", "Física", "Química", "Matemática", "Diseño", "Psicología", "Comunicaciones"], "problema": ["Los conceptos abstractos se entienden mejor cuando se conectan con situaciones conocidas, pero los ejemplos cotidianos tienen límites: una analogía puede simplificar demasiado o llevar a errores.", "Elegir buenos ejemplos y avisar dónde dejan de servir es parte de enseñar bien."], "desarrollar": ["Elige un concepto y crea tres analogías o ejemplos de la vida cotidiana. Para cada una, explica en qué se parece al concepto y en qué se diferencia, y qué errores podría provocar.", "Pruébalos con tres personas que no conozcan el concepto, observa cuál entienden mejor y qué malentendidos aparecen. Reescribe el material final incluyendo las limitaciones de cada ejemplo."], "ampliaciones": [{"titulo": "Varios conceptos", "aporta": "repite el proceso con otros dos conceptos."}, {"titulo": "Ejemplos locales", "aporta": "busca ejemplos de tu entorno cercano."}, {"titulo": "Dibujo o esquema", "aporta": "agrega una ilustración simple de cada ejemplo."}], "objetivos": ["Crear ejemplos cotidianos.", "Analizar sus límites.", "Probarlos con principiantes.", "Mejorar el material."], "habilidades": ["Pensamiento analógico.", "Comunicación.", "Diseño didáctico.", "Análisis crítico."], "herramientas": ["Un editor de documentos.", "Hojas para dibujar.", "Tres personas voluntarias."], "lineamientos": ["No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Señala siempre dónde la analogía deja de ser exacta."], "otroSector": "La misma técnica sirve para explicar conceptos técnicos a clientes o a equipos no especializados."}$a41sld$::jsonb,48),
('como-influye-el-lenguaje-utilizado-en-un-material-educativo-en-l','educacion',array['sociedad']::text[],'¿Cómo influye el lenguaje utilizado en un material educativo en la comprensión de sus lectores?','Compara dos versiones de un mismo texto, una con lenguaje técnico y otra con lenguaje claro, y mide cuánto entienden y cuánto tardan lectores que no conocen el tema.','Investigación','3 semanas',20,array['Lenguaje claro','Comprensión lectora']::text[],array['investigar']::text[],'propios',NULL,'educacion psicologia ingenieria de sistemas comunicaciones diseno trabajo social sociologia administracion redaccion clara. diseno de pruebas. analisis simple de datos. comunicacion. un texto tecnico. hoja de calculo. un cronometro.',$a42sld${"id": "como-influye-el-lenguaje-utilizado-en-un-material-educativo-en-l", "area": "educacion", "areas2": ["sociedad"], "titulo": "¿Cómo influye el lenguaje utilizado en un material educativo en la comprensión de sus lectores?", "resumen": "Compara dos versiones de un mismo texto, una con lenguaje técnico y otra con lenguaje claro, y mide cuánto entienden y cuánto tardan lectores que no conocen el tema.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 20, "etiquetas": ["Lenguaje claro", "Comprensión lectora"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Educación", "Psicología", "Ingeniería de Sistemas", "Comunicaciones", "Diseño", "Trabajo Social", "Sociología", "Administración"], "problema": ["Los textos educativos usan a veces palabras difíciles, frases largas o siglas sin explicar. Eso aleja a quien empieza, aunque el contenido sea importante.", "Medir el efecto del lenguaje permite justificar cuándo conviene simplificar."], "desarrollar": ["Elige un párrafo técnico de un tema que domines y reescríbelo en lenguaje claro sin perder exactitud. Prepara cinco preguntas de comprensión sobre el contenido.", "Pide a dos grupos pequeños de personas que lean cada versión, responde las preguntas y mide el tiempo que tardan. Compara resultados, revisa qué términos causaron dificultad y arma una lista de recomendaciones de lenguaje claro."], "ampliaciones": [{"titulo": "Índices de legibilidad", "aporta": "compara con fórmulas de legibilidad."}, {"titulo": "Glosario", "aporta": "agrega un glosario de términos y mide si ayuda."}, {"titulo": "Lenguaje inclusivo y accesible", "aporta": "revisa el texto para distintos lectores."}], "objetivos": ["Reescribir en lenguaje claro.", "Medir la comprensión.", "Comparar versiones.", "Redactar recomendaciones."], "habilidades": ["Redacción clara.", "Diseño de pruebas.", "Análisis simple de datos.", "Comunicación."], "herramientas": ["Un texto técnico.", "Hoja de cálculo.", "Un cronómetro."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "Mantén el significado: simplificar no es perder exactitud."], "otroSector": "El mismo estudio sirve para mejorar contratos, instructivos y comunicaciones a clientes."}$a42sld$::jsonb,49),
('guia-para-evaluar-si-una-fuente-de-internet-es-confiable-para-un','educacion',array['tecnologia','sociedad']::text[],'Guía para evaluar si una fuente de internet es confiable para un trabajo académico','Crea una lista de criterios para decidir si una fuente de internet sirve para un trabajo académico, como autor, fecha, respaldo y propósito, y pruébala con ejemplos reales.','Guía','2 a 3 semanas',18,array['Fuentes confiables','Alfabetización informacional']::text[],array['crear','investigar']::text[],'publicos',NULL,'educacion ingenieria de sistemas ciencia de datos psicologia comunicaciones estadistica diseno administracion evaluacion de fuentes. pensamiento critico. busqueda de informacion. redaccion. un buscador academico. hoja de calculo. un editor de documentos.',$a43sld${"id": "guia-para-evaluar-si-una-fuente-de-internet-es-confiable-para-un", "area": "educacion", "areas2": ["tecnologia", "sociedad"], "titulo": "Guía para evaluar si una fuente de internet es confiable para un trabajo académico", "resumen": "Crea una lista de criterios para decidir si una fuente de internet sirve para un trabajo académico, como autor, fecha, respaldo y propósito, y pruébala con ejemplos reales.", "tipo": "Guía", "tiempo": "2 a 3 semanas", "horas": 18, "etiquetas": ["Fuentes confiables", "Alfabetización informacional"], "intencion": ["crear", "investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Educación", "Ingeniería de Sistemas", "Ciencia de Datos", "Psicología", "Comunicaciones", "Estadística", "Diseño", "Administración"], "problema": ["En internet hay fuentes excelentes y otras que parecen serias pero no lo son. Muchos estudiantes usan lo primero que aparece o lo que tiene mejor diseño, sin verificar quién escribe, con qué respaldo y con qué fin.", "Una lista simple de criterios ayuda a decidir qué fuentes usar y cuáles descartar."], "desarrollar": ["Define de cinco a siete criterios, como autor identificado, fecha, referencias, institución detrás y claridad del propósito. Prueba la lista con ocho fuentes sobre un mismo tema, entre ellas artículos, sitios institucionales, blogs y redes, y califica cada una.", "Compara tu calificación con la de un compañero para ver si la lista es clara, ajústala y elabora una guía con ejemplos de fuentes buenas y malas, sin ridiculizar a nadie."], "ampliaciones": [{"titulo": "Verificación rápida", "aporta": "crea una versión de cinco preguntas para usar en un minuto."}, {"titulo": "Imágenes y datos", "aporta": "adapta la guía para evaluar imágenes y estadísticas."}, {"titulo": "Fuentes en otro idioma", "aporta": "agrega consejos para fuentes en inglés."}], "objetivos": ["Definir criterios de confiabilidad.", "Aplicarlos a fuentes reales.", "Contrastar con otra persona.", "Redactar la guía."], "habilidades": ["Evaluación de fuentes.", "Pensamiento crítico.", "Búsqueda de información.", "Redacción."], "herramientas": ["Un buscador académico.", "Hoja de cálculo.", "Un editor de documentos."], "lineamientos": ["Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Usa ejemplos de fuentes variadas y evita señalar a personas o instituciones concretas como engañosas sin respaldo.", "Verifica los criterios con guías oficiales de bibliotecas universitarias."], "otroSector": "La misma guía sirve para evaluar información en el trabajo, en noticias o en decisiones de salud."}$a43sld$::jsonb,50),
('disenando-una-experiencia-de-aprendizaje-para-ensenar-una-habili','educacion',array['arte']::text[],'Diseñando una experiencia de aprendizaje para enseñar una habilidad práctica desde cero','Elige una habilidad práctica, como cocinar algo, usar una herramienta o dibujar, y diseña un recorrido de aprendizaje para alguien que parte de cero, con etapas, práctica y forma de medir avances.','Plan','4 a 5 semanas',26,array['Habilidades prácticas','Diseño de aprendizaje']::text[],array['crear','resolver']::text[],'ficticios',NULL,'educacion psicologia ingenieria de sistemas comunicaciones diseno trabajo social sociologia administracion diseno de aprendizaje. observacion. comunicacion. planificacion. los materiales de la habilidad. un registro de avance. una persona voluntaria.',$a44sld${"id": "disenando-una-experiencia-de-aprendizaje-para-ensenar-una-habili", "area": "educacion", "areas2": ["arte"], "titulo": "Diseñando una experiencia de aprendizaje para enseñar una habilidad práctica desde cero", "resumen": "Elige una habilidad práctica, como cocinar algo, usar una herramienta o dibujar, y diseña un recorrido de aprendizaje para alguien que parte de cero, con etapas, práctica y forma de medir avances.", "tipo": "Plan", "tiempo": "4 a 5 semanas", "horas": 26, "etiquetas": ["Habilidades prácticas", "Diseño de aprendizaje"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Educación", "Psicología", "Ingeniería de Sistemas", "Comunicaciones", "Diseño", "Trabajo Social", "Sociología", "Administración"], "problema": ["Aprender una habilidad práctica no se logra solo mirando: requiere práctica con retroalimentación. Muchos tutoriales muestran el resultado final sin explicar el recorrido para quien empieza.", "Diseñar la ruta de aprendizaje desde cero permite entender qué necesita realmente un principiante."], "desarrollar": ["Define el resultado esperado al final del recorrido y divídelo en cuatro a seis etapas con objetivos, tareas de práctica y criterios para saber cuándo avanzar. Prepara los materiales y un registro de avance.", "Prueba el recorrido con una persona principiante, observa dónde se traba, qué la motiva y qué necesita aclarar, y ajusta la ruta. Presenta la versión final con consejos para quien enseñe."], "ampliaciones": [{"titulo": "Errores típicos", "aporta": "documenta los errores comunes de cada etapa."}, {"titulo": "Retroalimentación", "aporta": "diseña cómo dar comentarios en cada etapa."}, {"titulo": "Versión autoguiada", "aporta": "adapta la ruta para aprender sin apoyo."}], "objetivos": ["Definir un resultado de aprendizaje.", "Dividirlo en etapas.", "Probarlo con un principiante.", "Ajustar la ruta."], "habilidades": ["Diseño de aprendizaje.", "Observación.", "Comunicación.", "Planificación."], "herramientas": ["Los materiales de la habilidad.", "Un registro de avance.", "Una persona voluntaria."], "lineamientos": ["No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "Elige una habilidad segura: evita actividades con riesgo físico sin supervisión adecuada.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión."], "otroSector": "El mismo diseño sirve para capacitar en un oficio o en el uso de una herramienta de trabajo."}$a44sld$::jsonb,51),
('del-colegio-a-la-universidad-expectativas-realidad-y-dificultade','educacion',array['sociedad']::text[],'Del colegio a la universidad: expectativas, realidad y dificultades del primer ciclo','Recoge las experiencias de estudiantes sobre qué esperaban de la universidad, qué encontraron y qué dificultades enfrentaron en el primer ciclo, y organiza los hallazgos en un diagnóstico.','Investigación','4 semanas',26,array['Transición','Primer ciclo']::text[],array['investigar']::text[],'propios',NULL,'educacion psicologia ingenieria de sistemas comunicaciones diseno trabajo social sociologia administracion diseno de encuestas. analisis cualitativo. graficos. redaccion. un formulario en linea. hoja de calculo. un editor de graficos.',$a45sld${"id": "del-colegio-a-la-universidad-expectativas-realidad-y-dificultade", "area": "educacion", "areas2": ["sociedad"], "titulo": "Del colegio a la universidad: expectativas, realidad y dificultades del primer ciclo", "resumen": "Recoge las experiencias de estudiantes sobre qué esperaban de la universidad, qué encontraron y qué dificultades enfrentaron en el primer ciclo, y organiza los hallazgos en un diagnóstico.", "tipo": "Investigación", "tiempo": "4 semanas", "horas": 26, "etiquetas": ["Transición", "Primer ciclo"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Educación", "Psicología", "Ingeniería de Sistemas", "Comunicaciones", "Diseño", "Trabajo Social", "Sociología", "Administración"], "problema": ["El paso del colegio a la universidad cambia el ritmo, la autonomía, la forma de evaluar y el tipo de exigencia. Muchos ingresantes sienten que se perdieron algo que todos los demás ya saben.", "Entender las dificultades más comunes permite ayudar mejor y hacer sentir menos solos a los que ingresan."], "desarrollar": ["Diseña una encuesta anónima y voluntaria de diez preguntas para estudiantes de primer y segundo ciclo sobre qué esperaban, qué dificultades tuvieron, cómo las resolvieron y qué les hubiera servido. Aplícala a un grupo pequeño.", "Resume resultados en tablas y gráficos simples, agrupa las dificultades por tipo, como carga, organización del tiempo o estudio, y elabora un diagnóstico de cinco hallazgos con ejemplos."], "ampliaciones": [{"titulo": "Según carrera", "aporta": "compara resultados entre carreras si logras más respuestas."}, {"titulo": "Expectativas vs realidad", "aporta": "mide la diferencia entre lo esperado y lo vivido."}, {"titulo": "Pasos de ayuda", "aporta": "para cada dificultad, propón una acción concreta."}], "objetivos": ["Diseñar una encuesta anónima.", "Analizar las respuestas.", "Agrupar dificultades.", "Redactar un diagnóstico."], "habilidades": ["Diseño de encuestas.", "Análisis cualitativo.", "Gráficos.", "Redacción."], "herramientas": ["Un formulario en línea.", "Hoja de cálculo.", "Un editor de gráficos."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "Pide consentimiento, no recojas nombres ni datos que identifiquen y deja que las preguntas sean voluntarias."], "otroSector": "El mismo estudio sirve para entender la adaptación a un nuevo trabajo o a una nueva ciudad."}$a45sld$::jsonb,52),
('guia-practica-para-organizar-las-primeras-semanas-de-vida-univer','educacion',array['sociedad']::text[],'Guía práctica para organizar las primeras semanas de vida universitaria','Crea una guía de supervivencia académica para quienes ingresan, con estrategias para organizar el tiempo, estudiar, usar la biblioteca y pedir ayuda, en lenguaje cercano y con ejemplos reales.','Guía','3 a 4 semanas',24,array['Ingresantes','Adaptación']::text[],array['crear']::text[],'propios',NULL,'educacion psicologia ingenieria de sistemas comunicaciones diseno trabajo social sociologia administracion sintesis. redaccion clara. empatia. diseno de materiales. un editor de documentos. un editor de infografias. un formulario de opinion.',$a46sld${"id": "guia-practica-para-organizar-las-primeras-semanas-de-vida-univer", "area": "educacion", "areas2": ["sociedad"], "titulo": "Guía práctica para organizar las primeras semanas de vida universitaria", "resumen": "Crea una guía de supervivencia académica para quienes ingresan, con estrategias para organizar el tiempo, estudiar, usar la biblioteca y pedir ayuda, en lenguaje cercano y con ejemplos reales.", "tipo": "Guía", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Ingresantes", "Adaptación"], "intencion": ["crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Educación", "Psicología", "Ingeniería de Sistemas", "Comunicaciones", "Diseño", "Trabajo Social", "Sociología", "Administración"], "problema": ["Las primeras semanas de la universidad pueden ser caóticas: horarios nuevos, trámites, cursos exigentes y mucho material. Mucha información se transmite de boca en boca y quien llega sin contactos queda en desventaja.", "Una guía práctica, hecha por quienes ya pasaron por eso, ordena lo más importante."], "desarrollar": ["Con tu experiencia y la de tres a cinco compañeros, lista lo que más ayuda en las primeras semanas: cómo organizar el horario, cómo estudiar, qué trámites hacer primero, a quién preguntar y qué errores evitar. Prioriza diez consejos.", "Redacta la guía de forma breve y visual, pruébala con un ingresante y recoge qué le faltó o le sobró. Agrega una lista de verificación para la primera semana y otra para el primer mes."], "ampliaciones": [{"titulo": "Calendario de las primeras semanas", "aporta": "arma una línea de tiempo de qué hacer cada semana."}, {"titulo": "Mapa de recursos", "aporta": "agrega dónde pedir ayuda académica y de bienestar."}, {"titulo": "Versión para familias", "aporta": "adapta la guía para madres, padres o tutores."}], "objetivos": ["Reunir consejos de estudiantes.", "Priorizar lo esencial.", "Redactar una guía breve.", "Probarla con un ingresante."], "habilidades": ["Síntesis.", "Redacción clara.", "Empatía.", "Diseño de materiales."], "herramientas": ["Un editor de documentos.", "Un editor de infografías.", "Un formulario de opinión."], "lineamientos": ["No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "No des consejos de salud ni de situaciones personales graves: remite a los servicios de bienestar de la institución."], "otroSector": "La misma guía sirve para orientar a nuevos empleados en sus primeros días de trabajo."}$a46sld$::jsonb,53),
('que-conocimientos-previos-suelen-faltar-al-comenzar-una-asignatu','educacion',array[]::text[],'¿Qué conocimientos previos suelen faltar al comenzar una asignatura universitaria?','Identifica qué conocimientos previos hacen falta para un curso inicial y cuáles suelen faltar, y diseña una prueba corta de diagnóstico y una lista de recursos para repasar antes de empezar.','Investigación','3 a 4 semanas',22,array['Conocimientos previos','Diagnóstico']::text[],array['investigar','crear']::text[],'propios',NULL,'educacion psicologia ingenieria de sistemas comunicaciones diseno trabajo social sociologia administracion analisis de contenidos. diseno de pruebas. sintesis. pensamiento didactico. el silabo del curso. un formulario de preguntas. hoja de calculo.',$a47sld${"id": "que-conocimientos-previos-suelen-faltar-al-comenzar-una-asignatu", "area": "educacion", "areas2": [], "titulo": "¿Qué conocimientos previos suelen faltar al comenzar una asignatura universitaria?", "resumen": "Identifica qué conocimientos previos hacen falta para un curso inicial y cuáles suelen faltar, y diseña una prueba corta de diagnóstico y una lista de recursos para repasar antes de empezar.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 22, "etiquetas": ["Conocimientos previos", "Diagnóstico"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Educación", "Psicología", "Ingeniería de Sistemas", "Comunicaciones", "Diseño", "Trabajo Social", "Sociología", "Administración"], "problema": ["Algunos cursos asumen conocimientos que el colegio no siempre dio o que se olvidaron. Cuando faltan, el estudiante cree que no entiende el curso, cuando en realidad le falta una base.", "Detectar esos vacíos a tiempo permite repasarlos antes de que se vuelvan un obstáculo."], "desarrollar": ["Elige un curso inicial y, con el sílabo y una conversación con estudiantes que ya lo cursaron, lista los conocimientos previos que se usan en las primeras semanas. Clasifícalos por importancia.", "Crea una prueba corta de diagnóstico con una pregunta por conocimiento, aplícala a un grupo pequeño de voluntarios y observa cuáles fallan más. Arma una lista de recursos y ejercicios para repasar cada vacío."], "ampliaciones": [{"titulo": "Repaso de una semana", "aporta": "diseña un plan de repaso de siete días."}, {"titulo": "Antes de empezar", "aporta": "crea una guía para quienes ingresan o cambian de curso."}, {"titulo": "Comparar cursos", "aporta": "compara los conocimientos previos de dos cursos similares."}], "objetivos": ["Listar conocimientos previos.", "Diseñar una prueba de diagnóstico.", "Detectar vacíos frecuentes.", "Armar recursos de repaso."], "habilidades": ["Análisis de contenidos.", "Diseño de pruebas.", "Síntesis.", "Pensamiento didáctico."], "herramientas": ["El sílabo del curso.", "Un formulario de preguntas.", "Hoja de cálculo."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "Las pruebas son para ayudar a repasar, no para clasificar a nadie."], "otroSector": "El mismo diagnóstico sirve para evaluar qué sabe un nuevo equipo antes de una capacitación."}$a47sld$::jsonb,54),
('que-hubiera-querido-saber-antes-de-empezar-la-universidad','educacion',array['sociedad']::text[],'¿Qué hubiera querido saber antes de empezar la universidad?','Reúne las respuestas de estudiantes de distintos ciclos a la pregunta de qué les hubiera gustado saber antes de empezar, y organízalas en un material útil para ingresantes.','Investigación','3 semanas',20,array['Experiencias','Ingresantes']::text[],array['investigar','crear']::text[],'propios',NULL,'educacion psicologia ingenieria de sistemas comunicaciones diseno trabajo social sociologia administracion diseno de encuestas. analisis cualitativo. sintesis. comunicacion. un formulario en linea. hoja de calculo. un editor de infografias.',$a48sld${"id": "que-hubiera-querido-saber-antes-de-empezar-la-universidad", "area": "educacion", "areas2": ["sociedad"], "titulo": "¿Qué hubiera querido saber antes de empezar la universidad?", "resumen": "Reúne las respuestas de estudiantes de distintos ciclos a la pregunta de qué les hubiera gustado saber antes de empezar, y organízalas en un material útil para ingresantes.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 20, "etiquetas": ["Experiencias", "Ingresantes"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Educación", "Psicología", "Ingeniería de Sistemas", "Comunicaciones", "Diseño", "Trabajo Social", "Sociología", "Administración"], "problema": ["Quien ya pasó por la universidad sabe cosas que le habrían ahorrado tiempo y angustia. Esa información queda en conversaciones sueltas y se pierde, mientras cada ingresante vuelve a cometer los mismos errores.", "Recoger y ordenar esas lecciones crea un recurso valioso para quienes llegan."], "desarrollar": ["Haz una encuesta breve y anónima a estudiantes de diversos ciclos con una pregunta abierta y dos o tres de contexto, como ciclo y carrera. Reúne al menos 20 respuestas con consentimiento.", "Agrupa las respuestas por temas, como estudio, trámites, vida social y trabajo, cuenta cuántas veces aparece cada tema y selecciona consejos concretos. Presenta los resultados como un cartel o una guía de una página."], "ampliaciones": [{"titulo": "Por ciclo", "aporta": "compara lo que dicen quienes están en primer año y quienes están por terminar."}, {"titulo": "Frases clave", "aporta": "selecciona frases breves y anónimas para una publicación."}, {"titulo": "Video corto", "aporta": "crea un video con los consejos más repetidos."}], "objetivos": ["Recoger opiniones de estudiantes.", "Agrupar respuestas por tema.", "Priorizar consejos.", "Presentar los resultados."], "habilidades": ["Diseño de encuestas.", "Análisis cualitativo.", "Síntesis.", "Comunicación."], "herramientas": ["Un formulario en línea.", "Hoja de cálculo.", "Un editor de infografías."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "Publica solo respuestas anónimas y con permiso."], "otroSector": "La misma encuesta sirve para recoger aprendizajes de quienes pasaron por una práctica o un empleo."}$a48sld$::jsonb,55),
('materiales-para-ensenar-matematicas-basicas-a-ninas-y-ninos-con','educacion',array['ciencias']::text[],'Materiales para enseñar matemáticas básicas a niñas y niños con situaciones cotidianas','Diseña un conjunto de actividades de matemática básica basadas en situaciones cotidianas, como comprar, medir o repartir, para que niñas y niños aprendan con ejemplos cercanos.','Prototipo','3 a 4 semanas',24,array['Matemática','Niñas y niños']::text[],array['crear']::text[],'ficticios',NULL,'educacion biologia fisica quimica matematica diseno psicologia comunicaciones diseno didactico. comunicacion con ninos. creatividad. observacion. materiales reciclados. un editor de documentos. hojas para ilustrar.',$a49sld${"id": "materiales-para-ensenar-matematicas-basicas-a-ninas-y-ninos-con", "area": "educacion", "areas2": ["ciencias"], "titulo": "Materiales para enseñar matemáticas básicas a niñas y niños con situaciones cotidianas", "resumen": "Diseña un conjunto de actividades de matemática básica basadas en situaciones cotidianas, como comprar, medir o repartir, para que niñas y niños aprendan con ejemplos cercanos.", "tipo": "Prototipo", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Matemática", "Niñas y niños"], "intencion": ["crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Educación", "Biología", "Física", "Química", "Matemática", "Diseño", "Psicología", "Comunicaciones"], "problema": ["Muchos niños sienten que la matemática es abstracta y ajena. Cuando los ejercicios se parecen a lo que viven, como repartir una torta o contar vuelto, es más fácil entender para qué sirve.", "Materiales bien diseñados pueden hacer del aprendizaje algo más cercano y menos temido."], "desarrollar": ["Elige un tema, como fracciones, sumas con llevada o medidas, y diseña cinco a seis actividades con situaciones cotidianas, indicando el objetivo, los materiales y las instrucciones para el adulto que las guía.", "Prueba al menos dos actividades con un grupo pequeño de niñas y niños, con autorización y acompañamiento adulto, observa qué entendieron y qué les costó, y ajusta. Presenta una guía con las actividades finales."], "ampliaciones": [{"titulo": "Con material reciclado", "aporta": "adapta las actividades a objetos baratos o reciclados."}, {"titulo": "Mini evaluación", "aporta": "diseña preguntas para ver qué aprendieron."}, {"titulo": "Para familias", "aporta": "agrega consejos para que las familias practiquen en casa."}], "objetivos": ["Diseñar actividades cotidianas.", "Redactar instrucciones claras.", "Probarlas con niñas y niños.", "Mejorar el material."], "habilidades": ["Diseño didáctico.", "Comunicación con niños.", "Creatividad.", "Observación."], "herramientas": ["Materiales reciclados.", "Un editor de documentos.", "Hojas para ilustrar."], "lineamientos": ["Si pruebas el material con niñas y niños, hazlo con autorización de su familia o de la institución, sin fotos ni datos personales, y con un adulto presente.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Adapta el nivel de dificultad a la edad y no presentes la actividad como evaluación de los niños."], "otroSector": "El mismo enfoque sirve para educación de adultos o capacitación en educación financiera básica."}$a49sld$::jsonb,56),
('coleccion-de-actividades-para-ensenar-ciencias-naturales-a-escol','educacion',array['ciencias']::text[],'Colección de actividades para enseñar ciencias naturales a escolares con experimentos sencillos y objetos de casa','Reúne y prueba experimentos sencillos que expliquen conceptos de ciencias naturales con objetos que hay en casa, con instrucciones claras, preguntas guía y medidas de seguridad.','Prototipo','4 semanas',26,array['Ciencias naturales','Experimentos']::text[],array['crear']::text[],'ficticios',NULL,'educacion biologia fisica quimica matematica diseno psicologia comunicaciones metodo cientifico basico. seguridad en experimentos. redaccion para ninos. diseno de materiales. objetos de casa. un editor de documentos. camara o dibujos para ilustrar.',$a50sld${"id": "coleccion-de-actividades-para-ensenar-ciencias-naturales-a-escol", "area": "educacion", "areas2": ["ciencias"], "titulo": "Colección de actividades para enseñar ciencias naturales a escolares con experimentos sencillos y objetos de casa", "resumen": "Reúne y prueba experimentos sencillos que expliquen conceptos de ciencias naturales con objetos que hay en casa, con instrucciones claras, preguntas guía y medidas de seguridad.", "tipo": "Prototipo", "tiempo": "4 semanas", "horas": 26, "etiquetas": ["Ciencias naturales", "Experimentos"], "intencion": ["crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Educación", "Biología", "Física", "Química", "Matemática", "Diseño", "Psicología", "Comunicaciones"], "problema": ["Las ciencias se entienden mejor cuando se ven y se tocan, pero muchas escuelas y familias no tienen laboratorios. Con objetos cotidianos se pueden explicar ideas como la densidad, la presión o la reacción de ácidos y bases.", "Un buen experimento sencillo despierta curiosidad y enseña a observar y preguntar."], "desarrollar": ["Selecciona de cuatro a seis conceptos de ciencias naturales y, para cada uno, diseña un experimento con materiales de casa. Redacta una ficha con objetivo, materiales, pasos, qué observar, preguntas guía y una explicación sencilla.", "Revisa la seguridad de cada experimento, descarta lo que implique riesgo, pruébalo antes de enseñarlo y, si es posible, aplícalo con un grupo pequeño con autorización. Publica una colección de fichas ilustradas."], "ampliaciones": [{"titulo": "Registro del experimento", "aporta": "crea una hoja para que el niño anote predicciones y resultados."}, {"titulo": "Explicación para adultos", "aporta": "añade un apartado con la explicación científica más completa."}, {"titulo": "Retos de variación", "aporta": "propone variaciones para investigar más."}], "objetivos": ["Diseñar experimentos seguros.", "Redactar fichas claras.", "Probarlos.", "Organizar una colección."], "habilidades": ["Método científico básico.", "Seguridad en experimentos.", "Redacción para niños.", "Diseño de materiales."], "herramientas": ["Objetos de casa.", "Un editor de documentos.", "Cámara o dibujos para ilustrar."], "lineamientos": ["Si pruebas el material con niñas y niños, hazlo con autorización de su familia o de la institución, sin fotos ni datos personales, y con un adulto presente.", "Elige experimentos seguros, sin productos peligrosos ni fuego, y con supervisión de un adulto.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión."], "otroSector": "La misma colección sirve para actividades de museos de ciencias o ferias escolares."}$a50sld$::jsonb,57),
('disenando-un-juego-educativo-para-aprender-vocabulario-matematic','educacion',array['arte']::text[],'Diseñando un juego educativo para aprender vocabulario, matemáticas o ciencias','Diseña un juego de mesa, de cartas o de roles que enseñe vocabulario, matemática o ciencias, con reglas simples, objetivos de aprendizaje claros y una prueba con jugadores reales.','Prototipo','4 semanas',26,array['Juegos educativos','Gamificación']::text[],array['crear']::text[],'ficticios',NULL,'educacion psicologia ingenieria de sistemas comunicaciones diseno trabajo social sociologia administracion diseno de juegos. creatividad. pedagogia basica. pruebas con usuarios. cartulina y papel. un editor de documentos. jugadores voluntarios.',$a51sld${"id": "disenando-un-juego-educativo-para-aprender-vocabulario-matematic", "area": "educacion", "areas2": ["arte"], "titulo": "Diseñando un juego educativo para aprender vocabulario, matemáticas o ciencias", "resumen": "Diseña un juego de mesa, de cartas o de roles que enseñe vocabulario, matemática o ciencias, con reglas simples, objetivos de aprendizaje claros y una prueba con jugadores reales.", "tipo": "Prototipo", "tiempo": "4 semanas", "horas": 26, "etiquetas": ["Juegos educativos", "Gamificación"], "intencion": ["crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Educación", "Psicología", "Ingeniería de Sistemas", "Comunicaciones", "Diseño", "Trabajo Social", "Sociología", "Administración"], "problema": ["Muchos juegos educativos son ejercicios disfrazados: el aprendizaje no está en el juego, y por eso se abandonan. Un buen juego logra que jugar implique practicar lo que se quiere enseñar.", "Diseñar las reglas para que aprender sea parte natural del juego es el reto principal."], "desarrollar": ["Define qué se quiere enseñar y a quién, y diseña un juego con reglas simples, materiales y un sistema de puntos que premie el aprendizaje y no solo la suerte. Elabora un prototipo con cartulina o papel.", "Prueba el juego con tres a cinco personas, observa si se divierten y si practican lo que quieres enseñar, y ajusta las reglas. Escribe un manual breve con instrucciones y variantes."], "ampliaciones": [{"titulo": "Niveles de dificultad", "aporta": "diseña versiones para distintas edades o niveles."}, {"titulo": "Versión sin materiales", "aporta": "adapta el juego para jugarse sin nada especial."}, {"titulo": "Medir el aprendizaje", "aporta": "compara conocimientos antes y después de jugar."}], "objetivos": ["Definir objetivos de aprendizaje.", "Diseñar reglas del juego.", "Probar con jugadores.", "Redactar un manual."], "habilidades": ["Diseño de juegos.", "Creatividad.", "Pedagogía básica.", "Pruebas con usuarios."], "herramientas": ["Cartulina y papel.", "Un editor de documentos.", "Jugadores voluntarios."], "lineamientos": ["Si pruebas el material con niñas y niños, hazlo con autorización de su familia o de la institución, sin fotos ni datos personales, y con un adulto presente.", "Si se prueba con niños o adolescentes, que sea con autorización y sin datos personales.", "Evita copiar juegos comerciales: diseña tus propias reglas."], "otroSector": "El mismo enfoque sirve para dinámicas de capacitación en empresas o campañas de sensibilización."}$a51sld$::jsonb,58),
('recursos-educativos-para-ninas-y-ninos-sobre-temas-cotidianos-un','educacion',array['arte']::text[],'Recursos educativos para niñas y niños sobre temas cotidianos: una guía visual para escolares','Crea un recurso visual, como un cuento ilustrado, un cartel o una guía, que explique un tema cotidiano a escolares con lenguaje, ejemplos y dibujos adecuados a su edad.','Prototipo','3 a 4 semanas',24,array['Recursos infantiles','Guía visual']::text[],array['crear']::text[],'ficticios',NULL,'educacion psicologia ingenieria de sistemas comunicaciones diseno trabajo social sociologia administracion diseno grafico. comunicacion con ninos. sintesis. pruebas con usuarios. un editor de diseno o dibujo. hojas y colores. un editor de documentos.',$a52sld${"id": "recursos-educativos-para-ninas-y-ninos-sobre-temas-cotidianos-un", "area": "educacion", "areas2": ["arte"], "titulo": "Recursos educativos para niñas y niños sobre temas cotidianos: una guía visual para escolares", "resumen": "Crea un recurso visual, como un cuento ilustrado, un cartel o una guía, que explique un tema cotidiano a escolares con lenguaje, ejemplos y dibujos adecuados a su edad.", "tipo": "Prototipo", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Recursos infantiles", "Guía visual"], "intencion": ["crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Educación", "Psicología", "Ingeniería de Sistemas", "Comunicaciones", "Diseño", "Trabajo Social", "Sociología", "Administración"], "problema": ["Temas como el uso del agua, la higiene o cuidar las cosas se enseñan con textos aburridos o poco claros. A veces los materiales para niños son demasiado complejos o simplifican hasta confundir.", "Una guía visual bien pensada puede enseñar un tema sin abrumar."], "desarrollar": ["Elige un tema cotidiano y una edad de destino, define dos o tres ideas clave y crea un recurso visual con poco texto, ejemplos cercanos y dibujos claros. Considera accesibilidad, como tamaño de letra y contraste.", "Pruébalo con un grupo pequeño de niñas y niños, con autorización, pidiéndoles que expliquen con sus palabras lo que entendieron, y ajusta. Presenta la versión final con una breve guía para el adulto que lo use."], "ampliaciones": [{"titulo": "Versión para colorear", "aporta": "crea una versión interactiva para colorear y completar."}, {"titulo": "Cuento", "aporta": "convierte el tema en una historia corta."}, {"titulo": "Evaluación", "aporta": "agrega preguntas simples para ver qué entendieron."}], "objetivos": ["Seleccionar ideas clave.", "Diseñar un recurso visual.", "Probarlo con niñas y niños.", "Mejorar el material."], "habilidades": ["Diseño gráfico.", "Comunicación con niños.", "Síntesis.", "Pruebas con usuarios."], "herramientas": ["Un editor de diseño o dibujo.", "Hojas y colores.", "Un editor de documentos."], "lineamientos": ["Si pruebas el material con niñas y niños, hazlo con autorización de su familia o de la institución, sin fotos ni datos personales, y con un adulto presente.", "Usa dibujos propios o libres de derechos y evita estereotipos.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión."], "otroSector": "El mismo enfoque sirve para carteles informativos en centros de salud o municipalidades."}$a52sld$::jsonb,59)
